package com.galleryvote.config;
import java.util.Collection; import org.springframework.core.convert.converter.Converter; import org.springframework.security.authentication.AbstractAuthenticationToken; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;
public final class JwtSupport { private JwtSupport(){} public static Converter<Jwt,AbstractAuthenticationToken> authenticationConverter(){return jwt->{Collection<SimpleGrantedAuthority> a=java.util.List.of(new SimpleGrantedAuthority("ROLE_"+jwt.getClaimAsString("role")));return new JwtAuthenticationToken(jwt,a,jwt.getSubject());};} public static Long userId(org.springframework.security.core.Authentication a){return Long.valueOf(((Jwt)a.getPrincipal()).getClaimAsString("uid"));} }
